-- 3. Initial Profiles & User Stats (8 users)
on conflict (email) do nothing;

select p.id, v.eco_points, v.virtual_trees, 0
from (values
  ('abdalla.shamsi@example.com', 240, 3),
  ('mariam.kaabi@nis.edu.ae', 410, 5),
  ('sultan.m@greenventures.ae', 180, 2),
  ('fatima.hashemi@example.com', 350, 4),
  ('ahmed.mehairi@hct.ac.ae', 520, 7),
  ('maha.suwaidi@wavemakers.org', 600, 8),
  ('omar.marzouqi@example.com', 90, 1),
  ('admin@climatify.org', 1200, 15)
) as v(email, eco_points, virtual_trees)
join public.profiles p on lower(p.email) = v.email
on conflict (user_id) do update set
  eco_points = greatest(public.user_stats.eco_points, excluded.eco_points),
  virtual_trees = greatest(public.user_stats.virtual_trees, excluded.virtual_trees);

-- 4. Initial Contact Messages (2 messages)
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.contact_messages', 'id'), coalesce((select max(id) from public.contact_messages), 1), true);

-- 5. Initial Event Registrations (5 registrations)
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.event_registrations', 'id'), coalesce((select max(id) from public.event_registrations), 1), true);

-- 6. Initial Form Submissions (5 submissions)
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.form_submissions', 'id'), coalesce((select max(id) from public.form_submissions), 1), true);
